source.patch:
From 159215a82da88ca6c511194c8188e9df7a193998 Mon Sep 17 00:00:00 2001
From: Victorien Le Couviour--Tuffet <victorien@videolan.org>
Date: Tue, 7 Sep 2021 15:23:03 +0200
Subject: [PATCH] Fix lr_lpf_line re-allocation check

Credit to Oss-Fuzz.
---
 src/decode.c   | 13 +++++++------
 src/internal.h |  3 ++-
 2 files changed, 9 insertions(+), 7 deletions(-)

diff --git a/src/decode.c b/src/decode.c
index 82605eb..457703d 100644
--- a/src/decode.c
+++ b/src/decode.c
@@ -3082,23 +3082,24 @@ int dav1d_decode_frame_init(Dav1dFrameContext *const f) {
         f->lf.cdef_line_sz[1] = (int) uv_stride;
     }

+    const int num_lines = c->n_tc > 1 ? f->sbh * (4 << f->seq_hdr->sb128) : 12;
     const int lr_line_sz = ((f->sr_cur.p.p.w + 31) & ~31) << hbd;
-    if (lr_line_sz != f->lf.lr_line_sz) {
+    const size_t lr_plane_sz = num_lines * lr_line_sz;
+    if (lr_plane_sz != f->lf.lr_plane_sz) {
         dav1d_freep_aligned(&f->lf.lr_lpf_line[0]);
-        const int num_lines = c->n_tc > 1 ? f->sbh * (4 << f->seq_hdr->sb128) : 12;
         // lr simd may overread the input, so slightly over-allocate the lpf buffer
-        uint8_t *lr_ptr = dav1d_alloc_aligned(lr_line_sz * num_lines * 3 + 64, 32);
+        uint8_t *lr_ptr = dav1d_alloc_aligned(lr_plane_sz * 3 + 64, 32);
         if (!lr_ptr) {
-            f->lf.lr_line_sz = 0;
+            f->lf.lr_plane_sz = 0;
             goto error;
         }

         for (int pl = 0; pl <= 2; pl++) {
             f->lf.lr_lpf_line[pl] = lr_ptr;
-            lr_ptr += lr_line_sz * num_lines;
+            lr_ptr += lr_plane_sz;
         }

-        f->lf.lr_line_sz = lr_line_sz;
+        f->lf.lr_plane_sz = lr_plane_sz;
     }

     // update allocation for loopfilter masks
diff --git a/src/internal.h b/src/internal.h
index 6fe915d..c708a1a 100644
--- a/src/internal.h
+++ b/src/internal.h
@@ -272,7 +272,8 @@ struct Dav1dFrameContext {
         Av1Restoration *lr_mask;
         int top_pre_cdef_toggle;
         int mask_sz /* w*h */, lr_mask_sz, cdef_line_sz[2] /* stride */;
-        int lr_line_sz, re_sz /* h */;
+        size_t lr_plane_sz; /* w*sbh*4*is_sb128 if n_tc > 1, else w*12 */
+        int re_sz /* h */;
         ALIGN(Av1FilterLUT lim_lut, 16);
         int last_sharpness;
         uint8_t lvl[8 /* seg_id */][4 /* dir */][8 /* ref */][2 /* is_gmv */];
-- 
